**分析过程**

1. **第42-43行（searchFilter拼接）**：`this.opts.searchFilter.replace(/{{username}}/g, username)` 将用户输入直接替换进LDAP过滤器。攻击者传入 `*)(uid=*))(|(uid=*` 可注入任意过滤条件，绕过认证逻辑。
2. **第54-56行（_findUser调用）**：`self._findUser(username, callback)` 将未净化的输入传递给 `_findUser`，触发上述注入点。由于 `searchFilter` 由配置决定，但 `username` 来自外部请求参数。
3. **第104-106行（authenticate入口）**：`self._findUser(username, function (err, user))` 是唯一调用链起点，未对 `username` 做任何转义或白名单校验，直接进入第42行的替换。
4. **防御缺失**：代码中无 `ldapjs` 的参数化查询接口（如 `search` 方法支持绑定变量），也未使用 `escapeFilter` 或正则过滤特殊字符。攻击者可构造恶意LDAP过滤器，使认证逻辑失效或泄露数据。

```fix
/**
 * Conduct a search using the admin client. Used for fetching both
 * user and group information.
 *
 * @param searchBase {String} LDAP search base
 * @param options {Object} LDAP search options
 * @param {Function} `function (err, result)`.
 */
LdapAuth.prototype._search = function (searchBase, options, callback) {
  var self = this;

  // Fix: Escape special characters in filter to prevent LDAP injection
  if (options.filter && typeof options.filter === 'string') {
    options.filter = escapeFilter(options.filter);
  }

  self._adminBind(function (err) {
    if (err)
      return callback(err);

    self._adminClient.search(searchBase, options, function (err, result) {
      if (err)
        return callback(err);

      var items = [];
      result.on('searchEntry', function (entry) {
        items.push(entry.object);
        if (self.opts.includeRaw === true) {
          items[items.length - 1]._raw = entry.raw;
        }
      });

      result.on('error', callback);

      result.on('end', function (result) {
        if (result.status !== 0) {
          var err = 'non-zero status from LDAP search: ' + result.status;
          return callback(err);
        }
        return callback(null, items);
      });
    });
  });
};

// Helper to escape LDAP filter special characters
function escapeFilter(filter) {
  return filter.replace(/[()&|!<>~*]/g, '\\$&');
}
